mapper.select:
SELECT o.id, o.resource_id, 'OPEN' AS type,
       o.start_at, o.end_at, o.note, r.name AS resource_name
FROM resource_opening o
JOIN resource r ON r.id = o.resource_id
WHERE o.start_at < #{dayEnd}
  AND o.end_at > #{dayStart}

    AND o.resource_id = #{resourceId}

UNION ALL
SELECT b.id, b.resource_id, b.block_type AS type,
       b.start_at, b.end_at, b.reason, r.name AS resource_name
FROM resource_block b
JOIN resource r ON r.id = b.resource_id
WHERE b.start_at < #{dayEnd}
  AND b.end_at > #{dayStart}

    AND b.resource_id = #{resourceId}

ORDER BY start_at, id

SELECT id, resource_id, start_at, end_at, note
FROM resource_opening
WHERE id = #{id}

mapper.update:
UPDATE resource_opening
SET start_at = #{startAt}, end_at = #{endAt}, note = #{note}
WHERE id = #{id}

UPDATE resource_block
SET start_at = #{startAt}, end_at = #{endAt}, reason = #{reason}
WHERE id = #{id}
  AND block_type = 'TEACHING'

mapper.select:
SELECT id
FROM resource_opening
WHERE resource_id = #{resourceId}
  AND start_at < #{end}
  AND end_at > #{start}

    AND id <> #{excludeId}

ORDER BY id FOR UPDATE

SELECT id
FROM resource_block
WHERE resource_id = #{resourceId}
  AND block_type = 'TEACHING'
  AND start_at < #{end}
  AND end_at > #{start}

    AND id <> #{excludeId}

ORDER BY id FOR UPDATE
